def dinuc_shuffle(s):
    idx={'A':0,'C':1,'G':2,'T':3}; inv='ACGT'
    E=[[0]*4 for _ in range(4)]
    for i in range(len(s)): E[idx[s[i]]][idx[s[(i+1)%len(s)]]]+=1
    avail=[row[:] for row in E]
    stack=[random.randrange(4)]; cur=stack[0]; out=[]
    while stack:
        av=[j for j in range(4) if avail[cur][j]>0]
        if av:
            j=random.choice(av); avail[cur][j]-=1; stack.append(j); cur=j
        else:
            out.append(stack.pop()); cur=stack[-1] if stack else None
    out=out[::-1]
    return ''.join(inv[v] for v in out[:-1])

stops={'TAA','TAG','TGA'}
def stop_span_stats(s):
    # max distance between successive in-frame stops, any frame, total 'protected' nt
    best=0; bestpos=0; tot_inf=0
    for f in range(3):
        p=[i for i in range(f,len(s)-2,3) if s[i:i+3] in stops]
        for a,b in zip(p,p[1:]):
            if b-a> best: best=b-a
        tot_inf += p[0] if p else 0
    # distance from region edges to nearest stop
    e1=0
    for i in range(0,len(s)-2,3):
        if s[i:i+3] in stops: e1=i; break
    else: e1=len(s)
    e2=0
    for i in range(len(s)-3,-1,-3):
        if s[i:i+3] in stops: e2=len(s)-i; break
    else: e2=len(s)
    return best, tot_inf, e1, e2

